import{_ as o,o as a,c as e,ag as r}from"./chunks/framework.B5ULsuav.js";const u=JSON.parse('{"title":"金刚经27分-不说断灭相","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经27分-不说断灭相.md","filePath":"60-原文段落/金刚经27分-不说断灭相.md","lastUpdated":1778155802000}'),_={name:"60-原文段落/金刚经27分-不说断灭相.md"};function s(n,t,p,c,i,d){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="金刚经27分-不说断灭相" tabindex="-1">金刚经27分-不说断灭相 <a class="header-anchor" href="#金刚经27分-不说断灭相" aria-label="Permalink to &quot;金刚经27分-不说断灭相&quot;">​</a></h1><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/27了空居士讲《金刚经》-第二十七分无断无灭分20170414">27了空居士讲《金刚经》-第二十七分无断无灭分20170414</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>第七分 (注：应为第二十七分) 无断无灭分</strong></p><p><strong>须菩提，汝若作是念，如来不以具足相故，得阿耨多罗三藐三菩提。须菩提，莫作是念，如来不以具足相故，得阿耨多罗三藐三菩提。须菩提，汝若作是念，发阿耨多罗三藐三菩提心者，说诸法断灭。莫作是念。何以故？发阿耨多罗三藐三菩提心者，于法不说断灭相。</strong></p><p>……</p><p><strong>何以故？发阿耨多罗三藐三菩提心者，于法不说断灭相。</strong></p><p>如果加两个字，真正发阿耨多罗三藐三菩提心者，于法不说断灭相。一切法，他们都知道不是断灭的，所以他们不会说法都是断灭的，也就是法不是断灭的，其实法是非断非常。你说法是常的，永恒的，也不对，你说法是断灭的，也不对，所以这句话世尊就概括说&quot;发阿耨多罗三藐三菩提心者，于法不说断灭相&quot;一切法他都不会说那些是断灭的，当然也反过来，也不会说是永恒的。</p><p>这一段的前边说到&quot;不可以三十二相观如来&quot;，然后说&quot;若以色见我，以音声求我，是人行邪道，不能见如来。&quot;前边就是强调了不能着有，这一段是强调了不能着空。是这个意思，是跟前边的一分相呼应的。</p>',9)])])}const m=o(_,[["render",s]]);export{u as __pageData,m as default};
